package middleware

import (
	"log/slog"
	"net/http"
	"strings"

	"github.com/labstack/echo/v4"
	"github.com/sbomhub/sbomhub/internal/config"
	"github.com/sbomhub/sbomhub/internal/model"
	"github.com/sbomhub/sbomhub/internal/repository"
	"github.com/sbomhub/sbomhub/internal/service"
)

// apiKeyPrefix is the literal prefix used for tenant-/project-scoped API keys
// generated by APIKeyService.generateAPIKey (see internal/service/apikey.go:
// `return "sbh_" + hex.EncodeToString(bytes)[:32]`). The MultiAuth middleware
// uses this prefix to decide whether an `Authorization: Bearer ...` value
// should be validated against the API-key table or treated as a Clerk JWT.
const apiKeyPrefix = "sbh_"

// MultiAuth returns a middleware that accepts both Clerk session JWTs (used by
// the Next.js web UI) and API keys (used by the CLI / GitHub Actions). The
// middleware is the single source of truth for the canonical SBOM upload
// endpoint POST /api/v1/projects/:id/sbom — see Trust Rescue 9.3.1 (#9). The
// existing Auth() and APIKeyAuth() middlewares are intentionally left
// untouched so any route that needs strictly one auth model keeps working.
//
// Decision rule (see apiKeyCredential for the credential lookup itself):
//   - X-API-Key: <anything non-empty> → API key path. The header carries no
//     other kind of credential, so its mere presence is an API-key attempt.
//   - Authorization: Bearer sbh_... → API key path (apiKeyService.ValidateKey +
//     tenant context derived from the key's own tenant_id).
//   - Any other Bearer value → Clerk JWT path (delegates to Auth()).
//   - Self-hosted mode (no Clerk secret) with NEITHER header → falls
//     through to Auth()'s self-hosted handler, which provisions the default
//     tenant/user. This preserves the "self-host first" promise: a local
//     curl with no header still works against the local server.
//
// Failure modes:
//   - A presented API key that doesn't validate → 401 (does NOT fall through to
//     Clerk; an obviously-shaped API key that fails validation is a hard
//     denial so a leaked-and-revoked key cannot be retried as a JWT).
//   - Neither header, in SaaS mode → delegated to Auth(), which returns
//     401 with its usual error body.
func MultiAuth(
	cfg *config.Config,
	tenantRepo *repository.TenantRepository,
	userRepo *repository.UserRepository,
	apiKeyService *service.APIKeyService,
) echo.MiddlewareFunc {
	clerkAuth := Auth(cfg, tenantRepo, userRepo)

	return func(next echo.HandlerFunc) echo.HandlerFunc {
		clerkChain := clerkAuth(next)

		return func(c echo.Context) error {
			raw, presented := apiKeyCredential(c.Request())
			if presented && raw == "" {
				// A credential was presented that cannot be resolved to ONE
				// value (see apiKeyCredential). Guessing which one the caller
				// meant is the same mistake as ignoring it.
				slog.Debug("MultiAuth: ambiguous API-key header")
				return c.JSON(http.StatusUnauthorized, map[string]string{
					"error": "invalid API key",
				})
			}
			if presented {
				return handleAPIKeyAuth(c, raw, tenantRepo, userRepo, apiKeyService, next)
			}

			// Fall back to Clerk JWT (or self-hosted default) path.
			return clerkChain(c)
		}
	}
}

// apiKeyCredential reports the API-key credential a request presents, and
// whether it presented one at all.
//
// # Why X-API-Key is read here
//
// APIKeyAuth (apikey.go) has always accepted the key in EITHER header, and says
// so in the 401 body it hands to clients ("Use X-API-Key header or
// Authorization: Bearer <key>"). MultiAuth read only Authorization, which made
// the two authenticators disagree about what a credential is — on the same
// server, for the same key. Two shipped clients landed on the wrong side of
// that split: packages/mcp-server (src/client/api.ts) and the reusable
// .github/workflows/sbom-upload.yml, which POSTs an SBOM to the MultiAuth-
// fronted /api/v1/projects/:id/sbom with X-API-Key alone.
//
// # Why `presented` exists (fail-closed)
//
// Not reading the header was only half the defect. The other half is what
// happened next: with Authorization empty, the request fell through to Auth(),
// whose self-hosted branch provisions the DEFAULT tenant's Owner. So a request
// carrying a project-scoped key was served as an unscoped tenant Owner — the
// key discarded, apiKeyProjectScopeAllowed never consulted, and a 200 returned
// for a project the key is scoped away from (measured on a throwaway stack
// 2026-08-04; see multiauth_xapikey_integration_test.go for the numbers). That
// is M48's fail-open shape: a refusal degrading into a default.
//
// `presented` is therefore not "the value looks like a key" but "the caller
// meant to authenticate with one". When it is true the value MUST validate, and
// handleAPIKeyAuth answers 401 when it does not. Silently ignoring a supplied
// credential is never the safe branch, because the caller cannot see that it
// was ignored.
//
// # The two channels, and why they are not symmetric
//
//   - X-API-Key is an API-key-only header. Any non-empty value is an attempt,
//     `sbh_`-shaped or not, exactly as APIKeyAuth treats it.
//   - Authorization also carries Clerk session JWTs, so only the `sbh_` prefix
//     marks a Bearer value as an API key. Widening that would route every web
//     UI request into the API-key table.
//
// An EMPTY X-API-Key is treated as absent, matching APIKeyAuth's `if apiKey ==
// ""` fallback. That is the shape a shell produces when it expands an unset
// variable into `-H "X-API-Key: $KEY"`, and refusing it would break the
// self-host promise above for a request that carries no credential at all.
//
// Precedence is X-API-Key first, then Authorization — again APIKeyAuth's order.
// The two middlewares must resolve the same principal from the same request, or
// one credential pair would be one identity on /api/v1/mcp/* and another on
// /api/v1/projects/*. Both now go through pickSingleCredential, so they agree
// about duplicates as well as about precedence.
//
// # The two channels, and why they are not symmetric
//
//   - X-API-Key is an API-key-only header. Any non-empty value is an attempt,
//     `sbh_`-shaped or not, exactly as APIKeyAuth treats it.
//   - Authorization also carries Clerk session JWTs, so only the `sbh_` prefix
//     marks a Bearer value as an API key. Widening that would route every web
//     UI request into the API-key table. A duplicate Authorization whose
//     API-key candidates conflict is refused here; one whose values are all
//     Clerk JWTs is left to the Clerk path, which reads the first value and
//     answers 401 on an empty one — fail-closed already.
//
// Outcomes:
//
//	(v,  true)   exactly one distinct credential — use it
//	("", true)   a credential was presented but there is no single answer to
//	             "which one". MultiAuth answers 401 (see pickSingleCredential).
//	("", false)  no credential at all
func apiKeyCredential(r *http.Request) (raw string, presented bool) {
	if v, present, ambiguous := pickSingleCredential(
		r.Header.Values(APIKeyHeader), asIs,
	); ambiguous {
		return "", true
	} else if present {
		return v, true
	}

	if v, present, ambiguous := pickSingleCredential(
		r.Header.Values("Authorization"), bearerAPIKey,
	); ambiguous {
		return "", true
	} else if present {
		return v, true
	}

	return "", false
}

// pickSingleCredential collapses the values a request carried under ONE header
// name into a single decision.
//
// # Why every value is read (Codex R1 Medium, R2 Medium)
//
// HTTP lets a field name repeat and Go keeps every value, but `Header.Get`
// returns only the FIRST. Reading a credential with Get therefore made
//
//	X-API-Key:
//	X-API-Key: sbh_<a real key>
//
// look like no credential at all — the request fell through to the Clerk /
// self-hosted path and, in `anonymous` self-host, was served as the DEFAULT
// tenant's Owner. One empty header, prepended, silently strips a project-scoped
// key of its scope. The identical shape exists on `Authorization`, which is why
// both channels come through here.
//
// # Why two different values are a refusal, not a choice
//
// Answering with either one is a guess about which the caller meant, and "take
// the first" is exactly the rule that produced the defect above. Repeats of the
// SAME value are not ambiguous — that is one credential sent twice, which says
// nothing conflicting.
//
// # Cost (Codex R2 Medium)
//
// One pass, no inner loop, and it returns the moment a second DISTINCT value
// appears: the answer cannot change after that. A request stuffing thousands of
// distinct header lines (Go admits ~1 MiB of headers by default) therefore costs
// O(n) comparisons rather than O(n^2), on an UNAUTHENTICATED path.
//
// `extract` maps one raw header value to a credential candidate, and reports
// whether the value is a candidate at all — that is what keeps Clerk JWTs in
// Authorization from being counted as conflicting API keys.
func pickSingleCredential(
	values []string, extract func(string) (string, bool),
) (raw string, present, ambiguous bool) {
	for _, v := range values {
		candidate, ok := extract(v)
		if !ok || candidate == "" {
			continue
		}
		if !present {
			raw, present = candidate, true
			continue
		}
		if candidate != raw {
			return "", true, true
		}
	}
	return raw, present, false
}

// asIs: the whole header value is the credential (X-API-Key).
func asIs(v string) (string, bool) { return v, true }

// bearerAPIKey: an `Authorization: Bearer sbh_...` value, and nothing else.
// A Clerk JWT is not a candidate, so it neither authenticates here nor makes a
// duplicate look ambiguous.
func bearerAPIKey(v string) (string, bool) {
	token := strings.TrimPrefix(v, BearerPrefix)
	if token == v || !strings.HasPrefix(token, apiKeyPrefix) {
		return "", false
	}
	return token, true
}

// bearerAny: an `Authorization: Bearer <anything>` value. APIKeyAuth's route
// groups have no Clerk path, so every Bearer value there is meant as an API
// key — including one that predates the `sbh_` prefix. Kept separate from
// bearerAPIKey so tightening one does not silently tighten the other.
func bearerAny(v string) (string, bool) {
	token := strings.TrimPrefix(v, BearerPrefix)
	if token == v {
		return "", false
	}
	return token, true
}

// handleAPIKeyAuth mirrors the APIKeyAuth + APIKeyTenant pair as a single
// inline step so MultiAuth can swap between auth strategies without re-entering
// Echo's middleware chain. Keep the order in sync with apikey.go (validate →
// set ContextKeyAPI → SetCurrentTenant → ContextKeyTenantID).
//
// M1 Codex review #F14: in addition to tenant + API-key context, the
// API-key path now also populates ContextKeyRole (mapped from
// api_keys.permissions) and ContextKeyUserID (a synthetic per-tenant
// user). Without these, handlers that gate on TenantContext.CanWrite()
// would reject every CLI sbh_... key with 403, and Decide / Reanalyse
// would reject every API-key call with "user identity required". The
// previous implementation worked for the SBOM upload / read-back routes
// only because those handlers did not consult CanWrite() or UserID; the
// triage / vex-drafts routes do, and the CLI's `sbomhub triage` command
// targets them with Bearer sbh_... auth.
func handleAPIKeyAuth(
	c echo.Context,
	rawKey string,
	tenantRepo *repository.TenantRepository,
	userRepo *repository.UserRepository,
	apiKeyService *service.APIKeyService,
	next echo.HandlerFunc,
) error {
	ctx := c.Request().Context()

	key, err := apiKeyService.ValidateKey(ctx, rawKey)
	if err != nil {
		slog.Debug("MultiAuth: API key validation failed", "error", err)
		return c.JSON(http.StatusUnauthorized, map[string]string{
			"error": "invalid API key",
		})
	}
	c.Set(ContextKeyAPI, key)

	// M50 W2: a key with api_keys.project_id set may only act on that project.
	// This runs before SetCurrentTenant / GetOrCreateAPIKeyUser so a refusal
	// issues no SQL of its own, and before `next` so no MultiAuth-fronted
	// route can be reached without it. Tenant-level keys (project_id IS NULL)
	// return immediately and are unaffected. See project_scope.go for the
	// route table and the 403 rationale.
	if ok, err := apiKeyProjectScopeAllowed(c, key); !ok {
		return err
	}

	// API keys are tenant-scoped — every key carries a tenant_id by schema,
	// which is what enforces tenant isolation through Postgres RLS.
	if err := tenantRepo.SetCurrentTenant(ctx, key.TenantID); err != nil {
		slog.Error("MultiAuth: failed to set tenant context", "error", err)
		return c.JSON(http.StatusInternalServerError, map[string]string{
			"error": "failed to set tenant context",
		})
	}
	c.Set(ContextKeyTenantID, key.TenantID)

	// F14: map api_keys.permissions → ContextKeyRole so
	// TenantContext.CanWrite() / CanAdmin() behave correctly for the
	// API-key path. Triage / vex-drafts handlers gate on CanWrite() and
	// were previously unreachable for API-key clients because this
	// context value was never set (Role() defaulted to "" which fails
	// every allowlist check). The mapping defaults to RoleMember when
	// `permissions` is empty (matches APIKeyService's default of "write")
	// or unrecognised, so legacy keys created before this mapping keep
	// working with the documented write-capable default.
	c.Set(ContextKeyRole, roleFromAPIKeyPermissions(key.Permissions))

	// F14: resolve a synthetic per-tenant API-key user so
	// audit_logs.user_id (FK to users.id) and vex_drafts.decision_by
	// have a stable, non-NULL pointer to attribute API-key activity to.
	// One user is created per tenant on first use (idempotent lookup by
	// clerk_user_id = "api-key:<tenant_uuid>"), shared across all
	// subsequent API-key requests for that tenant. Operators can filter
	// audit_logs by name "API Key User" to isolate CLI/Actions traffic.
	apiUser, err := userRepo.GetOrCreateAPIKeyUser(ctx, key.TenantID)
	if err != nil {
		slog.Error("MultiAuth: failed to resolve API-key user", "error", err, "tenant_id", key.TenantID)
		return c.JSON(http.StatusInternalServerError, map[string]string{
			"error": "failed to resolve api-key user context",
		})
	}
	c.Set(ContextKeyUserID, apiUser.ID)
	c.Set(ContextKeyUser, apiUser)
	// ClerkUserID lets TenantContext.IsSelfHosted() distinguish API-key
	// requests from genuine self-hosted default-tenant requests. We do
	// not claim "self-hosted" here — the API key may have been issued in
	// SaaS mode — but we do leave a recognisable marker so future
	// debugging (and the Codex round 7+ reviewer) can tell the two
	// pathways apart in logs.
	c.Set(ContextKeyClerkUserID, "api-key:"+key.TenantID.String())

	return next(c)
}

// roleFromAPIKeyPermissions maps the api_keys.permissions string to the
// TenantContext role allowlist (model.RoleViewer / RoleMember / RoleAdmin /
// RoleOwner).
//
// Recognised values (case-insensitive, trimmed):
//   - "read"          → RoleViewer (no CanWrite, no CanAdmin)
//   - "write"         → RoleMember (CanWrite, no CanAdmin)
//   - "admin"/"owner" → RoleAdmin  (CanWrite, CanAdmin)
//
// Default (empty string OR any unrecognised value) → RoleViewer.
//
// M1 Codex review #F17 fix: the previous default was RoleMember, which
// meant a stored permission of "readonly", "none", or simply a typo got
// silently promoted to write-capable on every MultiAuth-fronted endpoint.
// That is a fail-open default in a security product. The fix flips the
// default to RoleViewer (fail-closed) so any value the service-side
// validation in apikey.go::CreateKey did not bless — including direct DB
// INSERTs and rows persisted before that validation was in place — is
// treated as the lowest-privilege role.
//
// Companion validation lives in IsKnownAPIKeyPermission below; callers
// that need to reject unknown values at creation time (rather than
// silently downgrade them at validation time) use that helper. The two
// together implement the fail-closed contract end-to-end: at creation
// the service refuses unknown values with 400; at validation the
// middleware refuses to grant them write power even if they slipped in
// through some other path.
func roleFromAPIKeyPermissions(perm string) string {
	switch strings.ToLower(strings.TrimSpace(perm)) {
	case "read":
		return model.RoleViewer
	case "admin", "owner":
		return model.RoleAdmin
	case "write":
		return model.RoleMember
	default:
		// F17: fail-closed. An empty string here normally only reaches
		// this branch via direct DB injection — APIKeyService.CreateKey
		// fills in "write" when the request omits permissions. Mapping
		// the unknown branch to RoleViewer rather than RoleMember means
		// that even if a row somehow ends up empty / typo'd, it cannot
		// be used to drive write endpoints.
		return model.RoleViewer
	}
}

// IsKnownAPIKeyPermission is re-exported here for callers that already
// import the middleware package; the canonical definition lives in
// model.IsKnownAPIKeyPermission. The helper had to move to the model
// package to break the middleware ↔ service import cycle introduced
// when APIKeyService.CreateKey started validating permissions through
// it (M1 Codex review #F17). See model/apikey.go for the rationale.
func IsKnownAPIKeyPermission(perm string) bool {
	return model.IsKnownAPIKeyPermission(perm)
}
